sys_script_client.script:
function onSubmit() {

	// We only check if Priority is Critical = P1
	if(g_form.getIntValue('priority') !== 1)
		return true;

	if(!confirm("Creating a P1 ticket will trigger the MI process/emergency escalation. Do you want to proceed?"))
	{
		nowapi.g_notification.show("warning", "You canceled the ticket creation", 6000);

		return false;
	}

	nowapi.g_notification.show("info", "Ticket created successfully", 6000);

}
